format_data:
{
  "header": {
    "columns": [
      {
        "label": "",
        "fields": [
          {
            "label": "Company Logo",
            "fieldname": "linked_field_lxeeuTKm",
            "fieldtype": "Linked Field",
            "show_label": "hide",
            "custom": 1,
            "width": "84px",
            "link_path": "company.company_logo"
          },
          {
            "label": "Spacer",
            "fieldname": "spacer_nCtaGVsw",
            "fieldtype": "Spacer",
            "custom": 1,
            "height": 20
          }
        ]
      }
    ],
    "gap": 0
  },
  "sections": [
    {
      "label": "",
      "columns": [
        {
          "label": "",
          "fields": [
            {
              "label": "Custom HTML",
              "fieldname": "custom_html_BxUQIJXO",
              "fieldtype": "HTML",
              "html": "<span>{{ frappe.utils.global_date_format(doc.offer_date,format='long') }}</span>\n",
              "custom_style": "text-align:right;\n",
              "custom": 1
            },
            {
              "label": "Spacer",
              "fieldname": "spacer_EIWRGeHV",
              "fieldtype": "Spacer",
              "custom": 1,
              "height": 30
            },
            {
              "label": "Text",
              "fieldname": "static_text_XyETeBcR",
              "fieldtype": "Static Text",
              "align": "center",
              "custom_style": "",
              "custom": 1,
              "text": "JOB OFFER LETTER",
              "bold": 1,
              "font_size": 16
            },
            {
              "label": "Spacer",
              "fieldname": "spacer_DwnFoRni",
              "fieldtype": "Spacer",
              "custom": 1,
              "height": 20
            }
          ]
        }
      ]
    },
    {
      "label": "",
      "columns": [
        {
          "label": "",
          "fields": [
            {
              "label": "Greeting",
              "fieldname": "custom_html_greeting",
              "fieldtype": "HTML",
              "html": "<p>Dear {{ doc.applicant_name }},</p>\n",
              "custom_style": "text-align:justify;",
              "custom": 1
            },
            {
              "label": "Introduction",
              "fieldname": "custom_html_intro",
              "fieldtype": "HTML",
              "html": "{%- set department = frappe.db.get_value(\"Department\", doc.department, \"department_name\") if doc.department else None -%}\n<p>We are pleased to offer you employment with {{ doc.company }} in the position of <b>{{ doc.designation }}</b>{% if department %}, in the {{ department }} department{% endif %}{% if doc.date_of_joining %}, with effect from {{ frappe.utils.global_date_format(doc.date_of_joining, format=\"medium\") }}{% endif %}.</p>\n",
              "custom_style": "text-align:justify;",
              "custom": 1
            },
            {
              "label": "Compensation",
              "fieldname": "custom_html_pay",
              "fieldtype": "HTML",
              "html": "{%- macro money(v) -%}{{ frappe.utils.fmt_money(v or 0, currency=doc.currency) }}{%- endmacro -%}\n{%- set last_row = doc.ctc_breakup[-1] if doc.ctc_breakup else None -%}\n{%- set take_home = last_row.per_cycle if last_row and last_row.is_summary else None -%}\n{%- if doc.ctc %}\n<p>Your total cost to company will be <b>{{ money(doc.ctc) }}</b> per annum.{% if take_home %} Your estimated monthly take-home, before the deduction of income tax, will be {{ money(take_home) }}.{% endif %} Your remuneration will be subject to all deductions required under applicable law.</p>\n{%- endif %}\n",
              "custom_style": "text-align:justify;",
              "custom": 1
            },
            {
              "label": "Probation and Notice",
              "fieldname": "custom_html_notice",
              "fieldtype": "HTML",
              "html": "{%- if doc.probation_period_days %}\n<p>You will serve a probationary period of {{ doc.probation_period_days }} days from your date of joining.{% if doc.notice_period_during_probation %} During probation, either party may terminate the employment by giving {{ doc.notice_period_during_probation }} days of written notice.{% else %} No notice period is required during probation.{% endif %}{% if doc.notice_number_of_days %} Upon confirmation of your employment, the notice period will be {{ doc.notice_number_of_days }} days by either party.{% endif %}</p>\n{%- elif doc.notice_number_of_days %}\n<p>Either party may terminate the employment by giving {{ doc.notice_number_of_days }} days of written notice.</p>\n{%- endif %}\n",
              "custom_style": "text-align:justify;",
              "custom": 1
            },
            {
              "label": "Leave and Policies",
              "fieldname": "custom_html_policies",
              "fieldtype": "HTML",
              "html": "<p>You will be entitled to paid leave and public holidays in accordance with the Company's policies. Your employment will be governed by the policies, rules and procedures of the Company, as amended from time to time, and these will be made available to you upon joining.</p>\n",
              "custom_style": "text-align:justify;",
              "custom": 1
            },
            {
              "label": "Verification and Validity",
              "fieldname": "custom_html_validity",
              "fieldtype": "HTML",
              "html": "<p>This offer is made subject to the satisfactory verification of your credentials, references and background. We will share the list of documents required before your date of joining.{% if doc.offer_valid_till %} It will remain open until <b>{{ frappe.utils.global_date_format(doc.offer_valid_till, format=\"medium\") }}</b>. Please confirm your acceptance in writing on or before that date, failing which this offer will lapse.{% else %} Please confirm your acceptance in writing.{% endif %}</p>\n",
              "custom_style": "text-align:justify;",
              "custom": 1
            },
            {
              "label": "Welcome",
              "fieldname": "custom_html_welcome",
              "fieldtype": "HTML",
              "html": "<p>We look forward to welcoming you to {{ doc.company }}.</p>\n",
              "custom_style": "text-align:justify;",
              "custom": 1
            },
            {
              "label": "Spacer",
              "fieldname": "spacer_QuROPYsW",
              "fieldtype": "Spacer",
              "custom": 1,
              "height": 30
            },
            {
              "label": "Custom HTML",
              "fieldname": "custom_html_CSNGozOA",
              "fieldtype": "HTML",
              "html": "<p>Sincerely,</p>",
              "custom": 1,
              "custom_style": "text-align:justify;"
            },
            {
              "label": "Signature",
              "fieldname": "signature",
              "fieldtype": "Attach Image",
              "show_label": "hide",
              "width": "200px"
            },
            {
              "label": "Spacer",
              "fieldname": "spacer_XaViauFb",
              "fieldtype": "Spacer",
              "custom": 1,
              "height": 10
            },
            {
              "label": "Sign-off",
              "fieldname": "custom_html_signoff",
              "fieldtype": "HTML",
              "html": "{%- set signatory = frappe.db.get_value(\"Employee\", {\"user_id\": doc.owner}, \"employee_name\") or frappe.get_fullname(doc.owner) -%}\n<p>{{ signatory }}<br>{{ doc.company }}</p>\n",
              "custom_style": "text-align:justify;",
              "custom": 1
            }
          ]
        }
      ]
    },
    {
      "label": "",
      "columns": [
        {
          "label": "",
          "fields": [
            {
              "label": "Text",
              "fieldname": "static_text_terms_and_conditions",
              "fieldtype": "Static Text",
              "custom": 1,
              "text": "TERMS AND CONDITIONS",
              "bold": 1,
              "font_size": 14,
              "custom_style": "margin:10px 0px;"
            },
            {
              "label": "Terms and Conditions",
              "fieldname": "terms",
              "fieldtype": "Text Editor",
              "show_label": "hide",
              "custom_style": "text-align:justify;"
            }
          ]
        }
      ],
      "visible_if": "doc.terms",
      "page_break": true
    },
    {
      "label": "",
      "columns": [
        {
          "label": "",
          "fields": [
            {
              "label": "Divider",
              "fieldname": "divider_accept_rule",
              "fieldtype": "Divider",
              "custom": 1,
              "custom_style": "margin:18px 0 12px;border-bottom-color:#d5dae0;"
            },
            {
              "label": "Text",
              "fieldname": "static_text_accept",
              "fieldtype": "Static Text",
              "custom": 1,
              "text": "DECLARATION OF ACCEPTANCE",
              "bold": 1,
              "font_size": 14,
              "custom_style": "margin:10px 0px;"
            },
            {
              "label": "Declaration",
              "fieldname": "custom_html_accept",
              "fieldtype": "HTML",
              "html": "<p>I have read and understood the terms and conditions set out in this letter, and I accept the offer of employment on the terms stated.</p>\n",
              "custom_style": "text-align:justify;",
              "custom": 1
            }
          ]
        }
      ],
      "keep_together": true
    },
    {
      "label": "",
      "columns": [
        {
          "label": "",
          "fields": [
            {
              "label": "Spacer",
              "fieldname": "spacer_accept_signature",
              "fieldtype": "Spacer",
              "custom": 1,
              "height": 40
            },
            {
              "label": "Divider",
              "fieldname": "divider_accept_signature",
              "fieldtype": "Divider",
              "custom": 1,
              "custom_style": "margin:0 0 4px;border-bottom-color:#1f272e;"
            },
            {
              "label": "Text",
              "fieldname": "static_text_accept_signature",
              "fieldtype": "Static Text",
              "custom": 1,
              "text": "Signature",
              "font_size": 12,
              "custom_style": "color:#6b7681;"
            },
            {
              "label": "Spacer",
              "fieldname": "spacer_accept_name",
              "fieldtype": "Spacer",
              "custom": 1,
              "height": 8
            },
            {
              "label": "Applicant Name",
              "fieldname": "applicant_name",
              "fieldtype": "Data",
              "show_label": "hide",
              "font_size": 12,
              "custom_style": "color:#6b7681;"
            }
          ]
        },
        {
          "label": "",
          "fields": [
            {
              "label": "Spacer",
              "fieldname": "spacer_accept_date",
              "fieldtype": "Spacer",
              "custom": 1,
              "height": 40
            },
            {
              "label": "Divider",
              "fieldname": "divider_accept_date",
              "fieldtype": "Divider",
              "custom": 1,
              "custom_style": "margin:0 0 4px;border-bottom-color:#1f272e;"
            },
            {
              "label": "Text",
              "fieldname": "static_text_accept_date",
              "fieldtype": "Static Text",
              "custom": 1,
              "text": "Date",
              "font_size": 12,
              "custom_style": "color:#6b7681;"
            }
          ]
        }
      ],
      "gap": 48,
      "keep_together": true
    }
  ],
  "footer": {
    "columns": [
      {
        "label": "",
        "fields": []
      }
    ]
  }
}
